            if first + pins > 10:
                raise ValueError("Two rolls in a frame cannot score more than 10")
            self.current.append(pins)
            if first + pins < 10:
                self.frames.append(self.current)
                self.finished = True
            return

        # Spare in the tenth frame: one bonus roll, anything up to 10.
        self.current.append(pins)
        self.frames.append(self.current)
        self.finished = True

    def _all_rolls(self):
        rolls = []
        for frame in self.frames:
            rolls.extend(frame)
